// @vitest-environment jsdom
import * as React from 'react';
import {act} from 'react';
import {createRoot, type Root} from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import {afterEach, beforeAll, beforeEach, describe, expect, it, vi} from 'vitest';

import {CpuLoadChart} from './CpuLoadChart';
import type {CpuLoadSource, CpuSample} from './cpuLoadSource';

type Listener = (sample: CpuSample) => void;

/** Ручной источник: тест сам решает, когда и сколько точек отдать. */
function createManualSource(timeline: number[], values: number[]) {
    const listeners = new Set<Listener>();
    const source: CpuLoadSource & {emit: (s: CpuSample) => void; listeners: Set<Listener>} = {
        getSnapshot: () => ({timeline, values}),
        subscribe(listener) {
            listeners.add(listener);
            return () => listeners.delete(listener);
        },
        emit: (sample) => listeners.forEach((l) => l(sample)),
        listeners,
    };
    return source;
}

/** jsdom не умеет рисовать: отдаём uPlot «никакой» 2D-контекст. */
function stubCanvas() {
    const noop = () => undefined;
    const ctx = new Proxy(
        {measureText: () => ({width: 20, fontBoundingBoxAscent: 10}), canvas: {}},
        {get: (target, key) => (key in target ? target[key as keyof typeof target] : noop)},
    );
    HTMLCanvasElement.prototype.getContext = (() => ctx) as unknown as HTMLCanvasElement['getContext'];
    HTMLCanvasElement.prototype.toDataURL = () => 'data:,';
}

const observed = {count: 0};
class ResizeObserverStub {
    observe() {
        observed.count++;
    }
    unobserve() {
        observed.count--;
    }
    disconnect() {}
}

let container: HTMLDivElement;
let root: Root;

function mount(ui: React.ReactElement) {
    act(() => root.render(ui));
}

beforeAll(() => {
    stubCanvas();
    vi.stubGlobal('ResizeObserver', ResizeObserverStub);
    (globalThis as {IS_REACT_ACT_ENVIRONMENT?: boolean}).IS_REACT_ACT_ENVIRONMENT = true;
});

beforeEach(() => {
    container = document.createElement('div');
    Object.defineProperties(container, {
        clientWidth: {value: 800},
        clientHeight: {value: 300},
    });
    document.body.appendChild(container);
    root = createRoot(container);
});

afterEach(() => {
    act(() => root.unmount());
    container.remove();
});

const STEP = 1000;
const WINDOW = 10 * STEP;

function makeHistory(end: number, points: number) {
    const timeline: number[] = [];
    const values: number[] = [];
    for (let i = points - 1; i >= 0; i--) {
        timeline.push(end - i * STEP);
        values.push(50);
    }
    return {timeline, values};
}

describe('CpuLoadChart', () => {
    it('renders a uPlot chart for the initial snapshot and subscribes to the source', () => {
        const {timeline, values} = makeHistory(100_000, 11);
        const source = createManualSource(timeline, values);
        mount(
            <ThemeProvider theme="light">
                <CpuLoadChart source={source} windowMs={WINDOW} />
            </ThemeProvider>,
        );
        expect(container.querySelector('.cpu-load-chart canvas')).not.toBeNull();
        expect(container.querySelector('.yagr_theme_light')).not.toBeNull();
        expect(source.listeners.size).toBe(1);
        expect(observed.count).toBe(1);
    });

    it('appends samples per animation frame and keeps only the window', () => {
        const {timeline, values} = makeHistory(100_000, 11);
        const source = createManualSource(timeline.slice(), values.slice());
        let rafCallback: FrameRequestCallback | null = null;
        vi.stubGlobal('requestAnimationFrame', (cb: FrameRequestCallback) => {
            rafCallback = cb;
            return 1;
        });
        vi.stubGlobal('cancelAnimationFrame', () => undefined);

        mount(
            <ThemeProvider theme="light">
                <CpuLoadChart source={source} windowMs={WINDOW} />
            </ThemeProvider>,
        );
        const yagrRoot = container.querySelector('.cpu-load-chart__canvas')!;
        // uPlot кладёт данные в u.data, достаём их через DOM → замыкание нельзя, поэтому
